"use client";

import React, { useState, useEffect } from "react";
import { Clock, ArrowRight } from "lucide-react";

export function ProductPreorderCard() {
  const [timeLeft, setTimeLeft] = useState(86400 * 3); // 3 days

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <span className="text-[9px] font-extrabold uppercase bg-violet-500/15 text-violet-300 px-2 py-0.5 rounded border border-violet-500/20 tracking-wider">Preorder Launch</span>
        <span className="text-[10px] text-muted-foreground font-mono flex items-center gap-1">
          <Clock className="w-3.5 h-3.5 text-violet-400" /> 3d remaining
        </span>
      </div>

      <div className="h-28 bg-secondary/20 rounded-xl mb-4 border border-white/[0.04] flex flex-col items-center justify-center">
        <p className="text-xs font-bold text-muted-foreground/60">Batch-4 Launch Package</p>
        <p className="text-lg font-black text-foreground">$149.00</p>
      </div>

      <button className="w-full py-2 bg-violet-600 hover:bg-violet-500 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5 transition-all">
        <span>Reserve Preorder Unit</span>
        <ArrowRight className="w-3.5 h-3.5" />
      </button>
    </div>
  );
}
